"""Shared cohort formulation search. Run with stage: screen, refine, validate.
Uses native public meals/physiology; coarse RK4 screening, full RK4 validation.
All selected designs are atomically checkpointed. No fitted patient parameters.
"""
import json, os, sys, time
import numpy as np
from gri_bench.api import load_instance, Experiment, individual_design, glucose_metrics, summarize, save_design
from gri_bench.physiology import fast_trace
OUT='/work/output/'
I=load_instance()

def design(a, ec=140, n=6, tau=5, leak=None):
    return {'mode':'responsive','parameters':dict(theta_a=a, relative_leak=I['bounds']['relative_leak'][0] if leak is None else leak, ec50_mg_dl=ec, hill_n=n, tau_min=tau, theta_L=4.)}

def evaluate(ex,d,steps=1):
    rows=[]
    for name,seed,variant,p,x,meals in ex.jobs:
        trace=fast_trace(p,x,meals,individual_design(d,I['tdi'][name]),substeps=steps)
        rows.append(dict(patient=name,seed=seed,variant=variant,metrics=glucose_metrics(trace)))
    return dict(summarize(rows),rows=rows)

def record(d,m,stage):
    with open(OUT+'history.jsonl','a') as f: f.write(json.dumps(dict(stage=stage,design=d,metrics=m))+'\n')

def main():
    ex=Experiment(I)
    t=time.process_time()
    for a in [.00035,.00045,.00055,.00065,.00075,.00085]:
        d=design(a); m=evaluate(ex,d); record(d,m,'screen')
        print(a,{k:v for k,v in m.items() if k!='rows'},flush=True)
    print('CPU',time.process_time()-t,flush=True)
if __name__=='__main__': main()
